import * as T from './vendor/three.module.js';

// Original condensed frame geometry. Source photographs remain authoritative.
function contour(shape,w,h){const points=[];for(let i=0;i<48;i++){const a=i/48*Math.PI*2,c=Math.cos(a),s=Math.sin(a),n=shape==='round'?2:shape==='square'?4:3.1;points.push(new T.Vector3(Math.sign(c)*Math.abs(c)**(2/n)*w/2,Math.sign(s)*Math.abs(s)**(2/n)*h/2,0));}return points;}
function acetate(w,p){const profile=p.frameProfile,base=new T.Color(p.color),light=new T.Color(profile.highlight||p.color),data=new Uint8Array(32*32*4);for(let y=0;y<32;y++)for(let x=0;x<32;x++){const v=(Math.sin(x*.44+y*.23)+Math.cos(y*.61-x*.18)+Math.sin(x*.13-y*.51))*.17+.46,c=base.clone().lerp(light,profile.pattern?Math.max(0,Math.min(1,v)):0),i=(y*32+x)*4;data.set([Math.round(c.r*255),Math.round(c.g*255),Math.round(c.b*255),255],i);}const texture=new T.DataTexture(data,32,32);texture.colorSpace=T.LinearSRGBColorSpace;texture.wrapS=texture.wrapT=T.RepeatWrapping;texture.needsUpdate=true;w.resources.add(texture);return texture;}
function lensGradient(w,profile){if(!profile.lensBottom)return null;const data=new Uint8Array(2*32*4),bottom=new T.Color(profile.lensBottom),top=new T.Color(profile.lens);for(let y=0;y<32;y++){const c=bottom.clone().lerp(top,y/31);for(let x=0;x<2;x++)data.set([c.r*255,c.g*255,c.b*255,255],(y*2+x)*4);}const texture=new T.DataTexture(data,2,32);texture.colorSpace=T.LinearSRGBColorSpace;texture.magFilter=T.LinearFilter;texture.needsUpdate=true;w.resources.add(texture);return texture;}
export function createFrameModel(w,p,{templeAngle=0}={}){
 const profile=p.frameProfile,g=new T.Group(),gradient=lensGradient(w,profile),rim=w.mat(p.color,{map:profile.metalRim?null:acetate(w,p),roughness:profile.metalRim?.25:.27,metalness:profile.metalRim?.78:.04,transparent:!!profile.transparent,opacity:profile.transparent?.82:1}),lens=w.mat(gradient?'#ffffff':profile.lens||'#465346',{map:gradient,roughness:.19,metalness:.04,transparent:true,opacity:profile.clearLens?.10:.72,depthWrite:!profile.clearLens,side:T.DoubleSide}),metal=w.mat(profile.temple||p.color,{roughness:.3,metalness:profile.metalRim?.78:profile.temple?.65:.05}),shape=profile.shape||'rounded',unit=profile.optical?4.4/profile.frameWidthMM:null,wide=unit?profile.lensWidthMM*unit:shape==='square'?1.98:1.88,high=unit?profile.lensHeightMM*unit:shape==='round'?1.72:shape==='square'?1.37:1.48,center=unit?(profile.lensWidthMM+profile.bridgeMM)*unit/2:1.17,radius=profile.rimRadius||.105,armX=2.16,depth=unit?profile.templeMM*unit*.72:3.15,bridge=unit?profile.bridgeMM*unit/2:.29;
 const tube=(points,r,material,parent=g,closed=false)=>w.mesh(new T.TubeGeometry(new T.CatmullRomCurve3(points,closed),closed?48:12,r,6,closed),material,parent);
 for(const sign of [-1,1]){const points=contour(shape,wide,high).map(v=>v.add(new T.Vector3(sign*center,0,0)));tube(points,radius,rim,g,true);const form=new T.Shape(contour(shape,wide-(unit?radius:.12),high-(unit?radius:.12)).map(v=>new T.Vector2(v.x,v.y))),geo=new T.ShapeGeometry(form,24),pos=geo.attributes.position,uv=geo.attributes.uv;for(let i=0;i<pos.count;i++)uv.setXY(i,pos.getX(i)/wide+.5,pos.getY(i)/high+.5);const pane=w.mesh(geo,lens,g);pane.position.set(sign*center,0,-.015);pane.userData.clearOpticalLens=!!profile.clearLens;const arm=new T.Group();arm.position.set(sign*armX,.12,0);arm.rotation.y=sign*templeAngle;g.add(arm);tube([new T.Vector3(0,0,0),new T.Vector3(sign*.28,0,-.6),new T.Vector3(sign*.3,-.04,-depth*.76),new T.Vector3(sign*.23,-.33,-depth)],profile.metalRim?.035:.085,metal,arm);const pin=w.mesh(new T.SphereGeometry(profile.metalRim?.05:.095,8,6),metal,g);pin.position.set(sign*(armX-.04),.15,.07);
  if(profile.nosePads){const pad=w.mesh(new T.SphereGeometry(1,10,8),profile.nosePads==='adjustable'?w.mat('#d8e0dc',{transparent:true,opacity:.5,roughness:.3}):rim,g);pad.position.set(sign*(bridge+.09),-.24,-.24);pad.scale.set(.09,.19,.12);}
  if(profile.tipColor){const tip=tube([new T.Vector3(sign*.3,-.04,-depth*.76),new T.Vector3(sign*.23,-.33,-depth)],.09,w.mat(profile.tipColor,{transparent:!!profile.tipClear,opacity:profile.tipClear?.48:1,roughness:.35}),arm);tip.userData.templeTip=true;}
 }
 tube([new T.Vector3(-bridge,.19,0),new T.Vector3(0,.31,.07),new T.Vector3(bridge,.19,0)],profile.metalRim?.035:.08,rim);g.userData={productId:p.id,source:p.source,frameShape:shape,frameColor:p.colorName,optical:!!profile.optical,volumetric:true,adapted:true};return g;
}
export function placeFrame(w,p,x,y,z,width,height,parent=w.scene){const model=createFrameModel(w,p,{templeAngle:.12}),bounds=new T.Box3().setFromObject(model),size=bounds.getSize(new T.Vector3()),k=Math.min(Math.min(width,12)/size.x,height/size.y),g=new T.Group();model.scale.setScalar(k);g.add(model);g.userData={...model.userData,displayStand:true};const stand=w.mat('#879084',{roughness:.72});w.box(0,-12.7,-2,11,.8,9,stand,g);w.box(0,-6.5,-1,1,11.6,1,stand,g);g.position.set(x,y,z);parent.add(g);return g;}
